using System;using System.Collections.Generic;using System.Threading;
// Autoteste 0.19.19 sem jogo: modo automático repete a macro 0 enquanto o principal mantém o mesmo monstro; selecionar a si mesmo para; manual continua uma vez por tecla.
class AttackContinuousTest {
 sealed class Fake:IAttackRuntime {public uint Current=0x80000101;public bool Valid=true,Alive=true,Fail;public int Starts,Stops;public uint Target(CharacterRef c){return Current;}public bool ValidTarget(CharacterRef c,uint t){return Valid;}public bool Running(CharacterRef c,uint combo,uint t){return Alive;}public AttackResult Start(CharacterRef c,uint t){int n=Interlocked.Increment(ref Starts);return Fail?new AttackResult{Message="falha"}:new AttackResult{Combo=(uint)(100+n),Message="atacando"};}public AttackResult Stop(CharacterRef c,uint combo,uint t){Interlocked.Increment(ref Stops);return new AttackResult();}public int Releases;public AttackResult Release(CharacterRef c){Releases++;return new AttackResult();}public int StepValue=1;public int Step(CharacterRef c,uint combo){return StepValue;}public int SupStarts,SupStops,SupReleases;public uint SupLeader;public AttackResult StartSupport(CharacterRef c,CharacterRef leader){int n=Interlocked.Increment(ref SupStarts);SupLeader=leader.Id;return new AttackResult{Combo=(uint)(500+n),Message="suporte"};}public bool RunningSupport(CharacterRef c,uint combo){return Alive;}public AttackResult StopSupport(CharacterRef c){SupStops++;return new AttackResult();}public AttackResult ReleaseSupport(CharacterRef c){SupReleases++;return new AttackResult();}}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static int Main(){try{var p=new CharacterRef{Pid=1,Id=1,Name="principal"};var a=new CharacterRef{Pid=2,Id=2,Name="sec"};var rt=new Fake();var notes=new List<string>();var c=new AttackController(rt,new HashSet<int>(),s=>notes.Add(s));
  c.Tick(p,new[]{a},true,true,false);Check(rt.Starts==1&&notes.Count==1,"automático inicia e registra uma vez");
  c.Tick(p,new[]{a},true,true,false);Check(rt.Starts==1,"macro em andamento não é reiniciada");
  rt.Alive=false;c.Tick(p,new[]{a},true,true,false);rt.Alive=true;c.Tick(p,new[]{a},true,true,false);Check(rt.Starts>=2&&c.Engaged(2),"macro terminada recomeça no mesmo alvo (combo contínuo)");
  Check(notes.Count==1,"repetições não enchem o registro");
  rt.Alive=false;rt.Fail=true;c.Tick(p,new[]{a},true,true,false);c.Tick(p,new[]{a},true,true,false);int afterFail=rt.Starts;c.Tick(p,new[]{a},true,true,false);Check(rt.Starts==afterFail,"falha aguarda 3 s antes de tentar de novo");Check(c.Engaged(2),"durante a espera o secundário continua em ataque (seguir não puxa)");
  rt.Fail=false;rt.Alive=true;Thread.Sleep(3100);c.Tick(p,new[]{a},true,true,false);Check(rt.Starts==afterFail+1&&c.Engaged(2),"depois da espera volta a atacar");
  rt.Current=1;c.Tick(p,new[]{a},true,true,false);Check(!c.Engaged(2)&&rt.Stops>=1,"selecionar a si mesmo para o ataque");Check(rt.Releases==1&&c.TakeReleased(),"selecionar a si mesmo: para, cancela a ação e manda seguir na hora (0.50.1)");int rel=rt.Releases;c.Tick(p,new[]{a},true,true,false);Check(rt.Releases==rel,"tirar o alvo acontece uma vez, não a cada ciclo");rt.Current=0x80000106;c.Tick(p,new[]{a},true,true,false);rt.Current=0x80000107;c.Tick(p,new[]{a},true,true,false);Check(rt.Releases==rel,"trocar de monstro não tira o alvo");rt.Current=1;c.Tick(p,new[]{a},true,true,false);
  int s0=rt.Starts;rt.Current=0x80000105;c.Tick(p,new[]{a},true,false,false);Check(rt.Starts==s0,"manual não começa sem tecla");c.Tick(p,new[]{a},true,false,true);rt.Alive=false;c.Tick(p,new[]{a},true,false,false);c.Tick(p,new[]{a},true,false,false);Check(rt.Starts==s0+1,"manual não repete sem nova tecla");
  {AttackController.StallSeconds=0.5;var rt2=new Fake();var n2=new List<string>();var c2=new AttackController(rt2,new HashSet<int>(),x=>n2.Add(x));c2.Tick(p,new[]{a},true,true,false);c2.Tick(p,new[]{a},true,true,false);Thread.Sleep(600);int st=rt2.Starts,sp=rt2.Stops;c2.Tick(p,new[]{a},true,true,false);Check(rt2.Stops==sp+1&&rt2.Starts==st+1&&n2.Exists(x=>x.Contains("travada no passo 1")),"macro presa no mesmo passo é parada e reiniciada");
   st=rt2.Starts;for(int i=0;i<4;i++){rt2.StepValue++;Thread.Sleep(200);c2.Tick(p,new[]{a},true,true,false);}Check(rt2.Starts==st,"macro que avança de passo não é reiniciada");AttackController.StallSeconds=5;}
  {var rt3=new Fake();var c3=new AttackController(rt3,new HashSet<int>(),x=>{});var sup=new HashSet<int>{2};var b=new CharacterRef{Pid=3,Id=3,Name="atk"};
   c3.Tick(p,new[]{a,b},true,true,false,sup);Check(rt3.SupStarts==1&&rt3.SupLeader==p.Id&&rt3.Starts==1,"Sup usa a macro 2 no líder; o outro ataca o monstro");
   int stopsBefore=rt3.Stops;rt3.Current=0x80000109;c3.Tick(p,new[]{a,b},true,true,false,sup);Check(rt3.SupStarts==1&&rt3.SupStops==0&&rt3.Starts==2,"trocar de monstro não reinicia o suporte");Check(rt3.Stops==stopsBefore,"trocar de monstro não faz rodada separada de parar (o novo início interrompe)");
   rt3.Alive=false;c3.Tick(p,new[]{a,b},true,true,false,sup);rt3.Alive=true;c3.Tick(p,new[]{a,b},true,true,false,sup);Check(rt3.SupStarts>=2,"suporte recomeça a macro 2 quando termina");
   rt3.Current=1;c3.Tick(p,new[]{a,b},true,true,false,sup);Check(rt3.SupStops>=1&&rt3.SupReleases==1&&rt3.Releases==1&&c3.TakeReleased(),"soltar o TG: suporte e atacante cancelam a ação e seguem");
   rt3.Current=0x8000010A;c3.Tick(p,new[]{a,b},true,true,false,new HashSet<int>());int sb=rt3.SupStarts;c3.Tick(p,new[]{a,b},true,true,false,sup);Check(rt3.SupStarts==sb+1,"mudar de Atk para Sup troca a macro do personagem");}
  Console.WriteLine("Ataque contínuo aprovado.");return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
